-- MP-0015: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0015: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0015: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('lim-guan-eng','muhammad-fawwaz-mohamad-jan','chow-kon-yeow') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0015: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('bagan','permatang pauh','batu kawan') and slug not in ('lim-guan-eng','muhammad-fawwaz-mohamad-jan','chow-kon-yeow')) then raise exception 'MP-0015: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0015:%' and (m.source_type <> 'editorial' or e.slug not in ('lim-guan-eng','muhammad-fawwaz-mohamad-jan','chow-kon-yeow') or m.import_key not like 'MP-0015:' || e.slug || ':%')) then raise exception 'MP-0015: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'lim-guan-eng','Lim Guan Eng','government','Member of the Dewan Rakyat','Bagan','Pulau Pinang','Lim Guan Eng represents Bagan, Pulau Pinang, in the Dewan Rakyat. A DAP member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4082','/portraits/lim-guan-eng.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P043.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4082"}, {"label": "DAP · representatives", "url": "https://dapmalaysia.org/pulau-pinang-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'muhammad-fawwaz-mohamad-jan','Muhammad Fawwaz Mohamad Jan','opposition','Member of the Dewan Rakyat','Permatang Pauh','Pulau Pinang','Muhammad Fawwaz Mohamad Jan represents Permatang Pauh, Pulau Pinang, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4083','/portraits/muhammad-fawwaz-mohamad-jan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P044.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4083"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'chow-kon-yeow','Chow Kon Yeow','government','Chief Minister of Penang; Member of the Dewan Rakyat','Batu Kawan','Pulau Pinang','Chow Kon Yeow represents Batu Kawan, Pulau Pinang, in the Dewan Rakyat. Current role: Chief Minister of Penang; Member of the Dewan Rakyat. A DAP member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4085','/portraits/chow-kon-yeow.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P046.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4085"}, {"label": "DAP · representatives", "url": "https://dapmalaysia.org/pulau-pinang-representatives/"}, {"label": "Penang · Chief Minister, 28 Aug 2026", "url": "https://www.buletinmutiara.com/move-beyond-just-support-cm-chow-on-women-representation/"}, {"label": "PBAPP · updated plant schedule, 4 Jun 2026", "url": "https://pba.com.my/pdf/news/2026/04062026_Pg-Water-Rates-01072026_YB-Zairil-KJ-Appendix.pdf"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('lim-guan-eng','muhammad-fawwaz-mohamad-jan','chow-kon-yeow') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0015: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0015:lim-guan-eng:university-study-assistance','Provide university study assistance to three Air Putih students','Education','achieved',null,null,null,null,'2026-08-20','https://www.buletinmutiara.com/three-air-putih-students-receive-university-study-assistance/','Lim Guan Eng presented three university-bound students with RM1,000 each.','Achieved covers this documented handover in his Air Putih state-assembly role. It is not a Bagan-wide university-support score. No earlier public promise was established; the date is the published delivery report.','2026-11-09','editorial',false from public.entities e where e.slug='lim-guan-eng' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0015:chow-kon-yeow:mengkuang-park-water-plant','Build the Mengkuang Park Water Treatment Plant','Infrastructure','in_progress',35,'2026-12-31','2026-05-09','https://www.buletinmutiara.com/mengkuang-park-wtp-on-track-for-completion-by-november-says-cm-chow/','2026-05-09','https://www.buletinmutiara.com/mengkuang-park-wtp-on-track-for-completion-by-november-says-cm-chow/','Chow described PBAPP’s RM250 million water-treatment plant as part of Penang’s water contingency programme.','35% is the published physical-progress snapshot on 9 May 2026, not a November measurement. A 4 June PBAPP release uses an end-2026 completion schedule, superseding the earlier November forecast. Completed handover was not verified.','2026-11-09','editorial',false from public.entities e where e.slug='chow-kon-yeow' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

